// Every PlotAxisItem capability, in the order the declaring class takes them.
template <typename Declaring>
struct PlotAxisItemCapabilities : public PlotAxisItemDirectionCapability<Declaring>,
                                  public PlotAxisItemScaleCapability<Declaring>,
                                  public PlotAxisItemMinimumCapability<Declaring>,
                                  public PlotAxisItemMaximumCapability<Declaring>,
                                  public PlotAxisItemLabelCapability<Declaring>,
                                  public PlotAxisItemAutoFitCapability<Declaring>,
                                  public PlotAxisItemFollowSpanCapability<Declaring> {};

